25	<html lang="en">
26	<head>
27	<meta charset="UTF-8">
28	<meta name="viewport" content="width=device-width, initial-scale=1.0">
29	<title>TIRx Tensor Layout — Interactive Demo</title>
30	<link rel="stylesheet" href="viz-base.css">
31	<script src="viz-base.js"></script>
32	<style>
33	  /* embed mode (?notitle / ?lock) */
34	  body.lock .preset-row, body.lock .main-controls, body.lock #status { display:none; }
35	  body.notitle, body.lock { padding:10px; }
36	  /* lock: lay panels at natural size; JS scales the whole block to fit the width */
37	  body.lock #panels { display:flex; flex-direction:column; align-items:flex-start; gap:20px; grid-template-columns:none; width:max-content; max-width:none; margin:0; }
38	
39	  /* Demo-specific overrides */
40	  .ti {
41	    padding:5px 9px; border:1px solid var(--border); border-radius:5px;
42	    font-family:'SF Mono','Fira Code',monospace; font-size:15px; color:var(--text);
43	    background:var(--surface);
44	  }
45	  .ti.expr { min-width:440px; max-width:70vw; }
46	  .ti.shape { width:84px; }
47	  select.ti { font-family:inherit; cursor:pointer; }
48	  select.ti:disabled { opacity:.45; cursor:not-allowed; }
49	
50	  /* preset = secondary helper (just loads an example into the two fields) */
51	  .preset-row { display:flex; align-items:center; gap:8px; justify-content:center;
52	    margin-bottom:8px; font-size:13px; }
53	  .preset-row .lbl { font-size:13px; }
54	  .preset-hint { color:var(--dim); font-size:13px; font-style:italic; }
55	
56	  /* shape + layout = the first-class inputs */
57	  .main-controls { display:flex; gap:20px; justify-content:center; align-items:flex-end;
58	    flex-wrap:wrap; padding:16px 20px; border:1px solid #c7d6f0; border-radius:10px;
59	    background:#f6f9ff; max-width:960px; margin:0 auto 10px; }
60	  .field { display:flex; flex-direction:column; gap:5px; }
61	  .field.grow { flex:1; min-width:300px; }
62	  .flbl { font-size:15px; font-weight:700; color:var(--text); }
63	  .flbl-sub { font-weight:500; color:var(--dim); font-size:13px;
64	    font-family:'SF Mono','Fira Code',monospace; }
65	  .field .ti { font-size:15px; padding:8px 11px; }
66	  .field .ti.expr { width:100%; min-width:0; max-width:none; }
67	  .sw-group { display:flex; gap:6px; }
68	  .sw-group .ti { font-size:15px; padding:8px 8px; }
69	
70	  #status { font-size:13px; font-family:'SF Mono','Fira Code',monospace; color:var(--dim);
71	    text-align:center; margin-bottom:14px; }
72	
73	  /* Stack the two panels vertically (logical on top, physical below) */
74	  .panels { grid-template-columns:1fr; max-width:1280px; align-items:start; }
75	  .grid { gap:2px; }
76	  .cell { aspect-ratio:1; font-size:15px; border-radius:5px; border-width:2px; }
77	  .cell.dm { opacity:.18; }
78	
79	  /* Right panel: physical-coordinate view (2D table or 1D wrapped tiles) */
80	  #phys { max-height:580px; overflow:auto; padding:2px; }
81	  .phys-table { display:grid; gap:3px; }
82	  .ax-hdr { font-size:12px; color:var(--dim); font-weight:600;
83	    font-family:'SF Mono','Fira Code',monospace; display:flex; align-items:center; justify-content:center; }
84	  .ax-hdr.row { justify-content:flex-end; padding-right:4px; white-space:nowrap; }
85	  .pcell { border:1px solid var(--border); border-radius:4px; min-height:30px; padding:2px;
86	    display:flex; flex-wrap:wrap; gap:2px; align-content:flex-start; justify-content:center; transition:all .15s; }
87	  .pcell.hov-cell { border-color:#222; box-shadow:0 0 7px rgba(59,130,246,.4); }
88	  .pcell.dm-cell { opacity:.16; }
89	  /* bank mode: pack the elements of one bank word side by side (same size as
90	     the logical-tensor cells), not stacked */
91	  .phys-table.bank-mode .pcell { flex-wrap:nowrap; gap:2px; padding:2px; }
92	
93	  .phys-1d { display:flex; flex-wrap:wrap; gap:8px; }
94	  .thread-tile { border:2px solid var(--border); border-radius:8px; padding:5px 6px 6px;
95	    background:var(--bg); min-width:54px; transition:all .15s; }
96	  .thread-tile.hov-tile { box-shadow:0 0 8px rgba(59,130,246,.35); border-color:#222; }
97	  .thread-tile.dm-tile { opacity:.2; }
98	  .thread-lbl { font-size:12px; font-weight:700; color:var(--dim);
99	    font-family:'SF Mono','Fira Code',monospace; text-align:center; margin-bottom:4px; white-space:nowrap; }
100	  .thread-slots { display:flex; flex-wrap:wrap; gap:2px; justify-content:center; }
101	
102	  .gcell {
103	    border-radius:3px; display:flex; align-items:center; justify-content:center;
104	    font-size:15px; font-weight:700; width:46px; height:46px; flex:0 0 auto; cursor:pointer;
105	    border:2px solid transparent; transition:all .15s;
106	  }
107	  .gcell.hov { border-color:#222; box-shadow:0 0 6px rgba(59,130,246,.45); }
108	  .gcell.dm  { opacity:.18; }
109	
110	  .formula-bar { max-width:1280px; }
111	  /* Larger labels/headers/legend for embedded (scaled) readability */
112	  .panel h2 { font-size:16px; }
113	  .panel .nota { font-size:13px; }
114	  .hdr { font-size:12px; }
115	  .rl { font-size:12px; }
116	  .li { font-size:15px; }
117	</style>
118	</head>
119	<body>
120	
121	<h1 id="page-title">TIRx Tensor Layout</h1>
122	<div class="sub" id="page-subtitle">how a <code>TileLayout</code> (shard / replica / offset) maps logical tensor elements to physical threads</div>
123	
124	<div class="preset-row">
125	  <span class="lbl" id="preset-label">load an example</span>
126	  <select id="preset" class="ti"></select>
127	  <span class="preset-hint" id="preset-hint">↓ fills the two fields below</span>
128	</div>
129	
130	<div class="main-controls">
131	  <div class="field">
132	    <label class="flbl" id="shape-label">Logical shape</label>
133	    <input id="shape" class="ti shape" value="4, 8" spellcheck="false">
134	  </div>
135	  <div class="field">
136	    <label class="flbl" id="swizzle-label">Swizzle (SMEM)</label>
137	    <div class="sw-group">
138	      <select id="dtype" class="ti"></select>
139	      <select id="swmode" class="ti"></select>
140	    </div>
141	    <div class="flbl-sub" id="swhint" hidden>applies to shared-memory layouts only (sole axis @m)</div>
142	  </div>
143	  <div class="field grow">
144	    <label class="flbl" id="layout-label">Tile layout&nbsp;&nbsp;<span class="flbl-sub">S[shard] + R[replica] + offset</span></label>
145	    <input id="expr" class="ti expr" value="S[(4,8):(8@laneid,1@laneid)]" spellcheck="false">
146	  </div>
147	</div>
148	<div id="status"></div>
149	
150	<div class="panels" id="panels">
151	  <div class="panel">
152	    <h2 id="logical-title">Logical tensor</h2>
153	    <div class="nota" id="n0"></div>
154	    <div class="grid" id="g0"></div>
155	  </div>
156	  <div class="panel">
157	    <h2 id="physical-title">Physical threads</h2>
158	    <div class="nota" id="nphys"></div>
159	    <div id="phys"></div>
160	  </div>
161	  <svg class="arrow-svg" id="arrow"></svg>
162	</div>
163	
164	<div class="formula-bar" id="fb"></div>
165	<div class="leg" id="lg"></div>
166	
167	<script>
168	(function () {
169	  var zh = new URLSearchParams(location.search).get('lang') === 'zh';
170	  window.TIRX_LAYOUT_LANG = zh ? 'zh' : 'en';
171	  if (!zh) return;
172	  document.documentElement.lang = 'zh-CN';
173	  document.title = 'TIRx Tensor Layout 交互图';
174	  document.getElementById('page-title').textContent = 'TIRx Tensor Layout';
175	  document.getElementById('page-subtitle').innerHTML =
176	    '<code>TileLayout</code> 如何通过 shard、replica 和 offset 将逻辑元素映射到物理位置';
177	  document.getElementById('preset-label').textContent = '载入示例';
178	  document.getElementById('preset-hint').textContent = '↓ 自动填入下面两个字段';
179	  document.getElementById('shape-label').textContent = '逻辑 shape';
180	  document.getElementById('swizzle-label').textContent = 'Swizzle（SMEM）';
181	  document.getElementById('swhint').textContent = '只适用于唯一物理轴为 @m 的 shared-memory layout';
182	  document.getElementById('layout-label').innerHTML =
183	    'Tile layout&nbsp;&nbsp;<span class="flbl-sub">S[shard] + R[replica] + offset</span>';
184	  document.getElementById('logical-title').textContent = '逻辑 Tensor';
185	  document.getElementById('physical-title').textContent = '物理位置';
186	})();
187	</script>
188	<script src="layout-demo.js"></script>
189	</body>
190	</html>
