16	 * specific language governing permissions and limitations
17	 * under the License.
18	 *
19	 * TIRx tensor-layout visualizer.
20	 *
21	 * The page shell, CSS vocabulary, and the draw()/hover/arrow interaction
22	 * pattern are adapted from the team's own course material
23	 * (mlsyscourse/slides-modern-gpu-programming, data-layout/site/demo/
24	 * tile_distributed.html). The TIRx S/R/O parser and the logical->physical
25	 * mapper below are original and mirror tvm/python/tvm/tirx/layout.py
26	 * (_flatten_coord / _split_coord and the TileLayout forward mapping).
27	 * This file is NOT derived from any third-party layout demo.
28	 */
29	
30	'use strict';
31	
32	const ZH = window.TIRX_LAYOUT_LANG === 'zh';
33	function tr(en, zh) { return ZH ? zh : en; }
34	
35	// ── TIRx named axes (from tvm/python/tvm/tirx/layout.py _AXIS_NAMES, plus the
36	// device axis `pid` used by distributed layouts) ──────────────────────────────
37	const AXIS_ORDER = [
38	  'pid', 'bx', 'by', 'bz', 'cbx', 'cby', 'cbz', 'tx',
39	  'warpid', 'laneid', 'wgid', 'tid_in_wg', 'wid_in_wg', 'tid',
40	  'm', 'P', 'F', 'Bank', 'TCol', 'TLane',
41	];
42	// "Owner" axes name a physical unit that owns data (threads, devices); the rest
43	// (m, P, F, Bank, TCol, TLane) are storage/memory coordinates within an owner.
44	const OWNER_AXES = new Set([
45	  'pid', 'bx', 'by', 'bz', 'cbx', 'cby', 'cbz', 'tx',
46	  'warpid', 'laneid', 'wgid', 'tid_in_wg', 'wid_in_wg', 'tid',
47	]);
48	const KNOWN_AXES = new Set(AXIS_ORDER);
49	const MAX_ELEMENTS = 1024;  // render cap
50	
51	function isOwnerAxis(a) { return OWNER_AXES.has(a); }
52	function product(arr) { return arr.reduce((a, b) => a * b, 1); }
53	
54	// ── Parser ───────────────────────────────────────────────────────────────────
55	// Grammar mirrors layout.py: S[shape:stride] + R[shape:stride] + offset,
56	// stride/offset terms are "n@axis" (a bare int defaults to axis "m").
57	
58	function splitTopLevel(s, sep) {
59	  const out = [];
60	  let depth = 0, cur = '';
61	  for (const ch of s) {
62	    if (ch === '(' || ch === '[') depth++;
63	    else if (ch === ')' || ch === ']') {
64	      depth--;
65	      if (depth < 0) throw new Error('unmatched closing bracket or parenthesis');
66	    }
67	    if (ch === sep && depth === 0) { out.push(cur); cur = ''; }
68	    else cur += ch;
69	  }
70	  if (depth !== 0) throw new Error('unmatched opening bracket or parenthesis');
71	  out.push(cur);
72	  return out;
73	}
74	
75	function stripParens(s) {
76	  s = s.trim();
77	  if (s.startsWith('(') && s.endsWith(')')) return s.slice(1, -1);
78	  return s;
79	}
80	
81	function parseIntStrict(s) {
82	  const t = s.trim();
83	  if (!/^-?\d+$/.test(t)) throw new Error(`expected integer, got "${t}"`);
84	  return parseInt(t, 10);
85	}
86	
87	function parseTerm(tok) {
88	  const t = tok.trim();
89	  if (t.includes('@')) {
90	    const parts = t.split('@');
91	    if (parts.length !== 2) throw new Error(`bad term "${t}"`);
92	    const numPart = parts[0].trim();
93	    const axis = parts[1].trim();
94	    if (!KNOWN_AXES.has(axis)) throw new Error(`unknown axis "${axis}"`);
95	    const stride = numPart === '' ? 1 : parseIntStrict(numPart);
96	    return { stride, axis };
97	  }
98	  if (/^-?\d+$/.test(t)) return { stride: parseInt(t, 10), axis: 'm' };
99	  if (KNOWN_AXES.has(t)) return { stride: 1, axis: t };
100	  throw new Error(`bad term "${t}"`);
101	}
102	
103	function defaultStrides(extents) {
104	  const n = extents.length;
105	  const strides = new Array(n).fill(1);
106	  for (let i = n - 2; i >= 0; i--) strides[i] = strides[i + 1] * extents[i + 1];
107	  return strides;
108	}
109	
110	function parseExtents(s) {
111	  // Parse a comma-separated extent list and reject non-positive / oversized
112	  // extents, so bad input (e.g. R[1000000:...] or a 0/negative extent) can't
113	  // NaN-propagate or freeze the tab with huge loops in physOwners().
114	  const extents = splitTopLevel(stripParens(s), ',').map(parseIntStrict);
115	  for (const e of extents) {
116	    if (e <= 0) throw new Error(`extent must be positive, got ${e}`);
117	    if (e > MAX_ELEMENTS) throw new Error(`extent ${e} exceeds maximum ${MAX_ELEMENTS}`);
118	  }
119	  return extents;
120	}
121	
122	function parseBracket(inner) {
123	  const parts = splitTopLevel(inner, ':');
124	  if (parts.length === 1) {
125	    const extents = parseExtents(parts[0]);
126	    const strides = defaultStrides(extents);
127	    return extents.map((e, i) => ({ extent: e, stride: strides[i], axis: 'm' }));
128	  }
129	  if (parts.length !== 2) throw new Error('layout bracket must be "shape : stride"');
130	  const extents = parseExtents(parts[0]);
131	  const terms = splitTopLevel(stripParens(parts[1]), ',').map(parseTerm);
132	  if (extents.length !== terms.length) {
133	    throw new Error(`shape has ${extents.length} dims but stride has ${terms.length}`);
134	  }
135	  return extents.map((e, i) => ({ extent: e, stride: terms[i].stride, axis: terms[i].axis }));
136	}
137	
138	function bracketBody(piece, prefix) {
139	  const open = piece.indexOf('[');
140	  const close = piece.lastIndexOf(']');
141	  if (open < 0 || close < 0 || close < open) throw new Error(`malformed ${prefix}[...]`);
142	  return piece.slice(open + 1, close);
143	}
144	
145	function callBody(src, name) {
146	  const s = src.trim();
147	  const open = s.indexOf('(');
148	  if (open < 0 || s.slice(0, open).trim() !== name) return null;
149	  let depth = 0;
150	  let close = -1;
151	  for (let i = open; i < s.length; i++) {
152	    if (s[i] === '(') depth++;
153	    else if (s[i] === ')') {
154	      depth--;
155	      if (depth < 0) throw new Error(`unmatched closing parenthesis in ${name}`);
156	      if (depth === 0) { close = i; break; }
157	    }
158	  }
159	  if (close < 0) throw new Error(`unmatched opening parenthesis in ${name}`);
160	  if (s.slice(close + 1).trim() !== '') throw new Error(`unexpected text after ${name}(...)`);
161	  return s.slice(open + 1, close);
162	}
163	
164	function parseComposeLayout(src) {
165	  // Exact 0.26 API form:
166	  // ComposeLayout(per_element, swizzle_len, atom_len,
167	  //               tile_layout=TileLayout(...), swizzle_inner=True)
168	  const body = callBody(src, 'ComposeLayout');
169	  if (body === null) return { swizzle: null, rest: src };
170	  const args = splitTopLevel(body, ',').map((s) => s.trim());
171	  // Python permits one trailing comma, but not a missing argument in any other
172	  // position. Keep the demo's accepted call syntax aligned with ComposeLayout.
173	  if (args.length && args[args.length - 1] === '') args.pop();
174	  if (args.some((s) => s === '')) throw new Error('empty ComposeLayout argument');
175	  const params = ['per_element', 'swizzle_len', 'atom_len', 'tile_layout', 'swizzle_inner'];
176	  const positional = [];
177	  const named = Object.create(null);
178	  let sawNamed = false;
179	  for (const arg of args) {
180	    const kv = splitTopLevel(arg, '=').map((s) => s.trim());
181	    if (kv.length === 1) {
182	      if (sawNamed) throw new Error('positional argument follows keyword argument');
183	      if (positional.length === params.length) {
184	        throw new Error('ComposeLayout takes at most 5 arguments');
185	      }
186	      positional.push(kv[0]);
187	    } else if (kv.length === 2 && kv[0] !== '' && kv[1] !== '') {
188	      sawNamed = true;
189	      const name = kv[0];
190	      if (!params.includes(name)) {
191	        throw new Error('unexpected ComposeLayout keyword "' + name + '"');
192	      }
193	      if (Object.hasOwn(named, name)) {
194	        throw new Error('duplicate ComposeLayout keyword "' + name + '"');
195	      }
196	      named[name] = kv[1];
197	    } else {
198	      throw new Error('bad ComposeLayout argument "' + arg + '"');
199	    }
200	  }
201	  for (let i = 0; i < positional.length; i++) {
202	    if (Object.hasOwn(named, params[i])) {
203	      throw new Error('multiple values for ComposeLayout argument "' + params[i] + '"');
204	    }
205	  }
206	  const pick = (name, index) => named[name] === undefined ? positional[index] : named[name];
207	  const perRaw = pick('per_element', 0);
208	  const lenRaw = pick('swizzle_len', 1);
209	  const atomRaw = pick('atom_len', 2);
210	  if (perRaw === undefined || lenRaw === undefined || atomRaw === undefined) {
211	    throw new Error('ComposeLayout needs per_element, swizzle_len, and atom_len');
212	  }
213	  const tileRaw = pick('tile_layout', 3);
214	  if (tileRaw === undefined) throw new Error('ComposeLayout needs tile_layout=TileLayout(...)');
215	  const tileBody = callBody(tileRaw, 'TileLayout');
216	  if (tileBody === null) throw new Error('tile_layout must be TileLayout(...)');
217	  const per_element = parseIntStrict(perRaw);
218	  const swizzle_len = parseIntStrict(lenRaw);
219	  const atom_len = parseIntStrict(atomRaw);
220	  if (per_element < 0 || swizzle_len < 0 || atom_len < swizzle_len
221	      || per_element >= 31 || atom_len >= 31) {
222	    // atom_len/per_element feed 32-bit bitwise shifts in swizzleAddr; cap < 31.
223	    throw new Error('swizzle requires 0≤per_element<31, swizzle_len≥0, swizzle_len≤atom_len<31');
224	  }
225	  const innerRaw = pick('swizzle_inner', 4);
226	  let inner = true;
227	  if (innerRaw !== undefined) {
228	    if (/^(True|1)$/.test(innerRaw)) inner = true;
229	    else if (/^(False|0)$/.test(innerRaw)) inner = false;
230	    else throw new Error('swizzle_inner must be True or False');
231	  }
232	  return { swizzle: { per_element, swizzle_len, atom_len, inner }, rest: tileBody.trim() };
233	}
234	
235	function parseLayout(srcRaw) {
236	  const { swizzle, rest } = parseComposeLayout(srcRaw.trim());
237	  const src = rest;
238	  const layout = { shard: [], replica: [], offset: {}, swizzle };
239	  let sawShard = false;
240	  for (let piece of splitTopLevel(src, '+')) {
241	    piece = piece.trim();
242	    if (piece === '') continue;
243	    if (piece.startsWith('S[')) {
244	      layout.shard = parseBracket(bracketBody(piece, 'S'));
245	      sawShard = true;
246	    } else if (piece.startsWith('R[')) {
247	      layout.replica = parseBracket(bracketBody(piece, 'R'));
248	    } else {
249	      const t = parseTerm(piece);
250	      layout.offset[t.axis] = (layout.offset[t.axis] || 0) + t.stride;
251	    }
252	  }
253	  if (!sawShard) throw new Error('layout needs a shard term, e.g. S[...]');
254	  return layout;
255	}
256	
257	// ── Mapper (mirrors layout.py _flatten_coord / _split_coord + forward map) ─────
258	
259	function flattenCoord(coord, shape) {
260	  let flat = 0;
261	  for (let i = 0; i < shape.length; i++) flat = flat * shape[i] + coord[i];
262	  return flat;
263	}
264	
265	function splitCoord(flat, extents) {
266	  const n = extents.length;
267	  const res = new Array(n);
268	  let remaining = flat;
269	  for (let i = n - 1; i >= 0; i--) {
270	    if (i === 0) res[0] = remaining;
271	    else { res[i] = remaining % extents[i]; remaining = Math.floor(remaining / extents[i]); }
272	  }
273	  return res;
274	}
275	
276	function coordFromFlat(flat, shape) { return splitCoord(flat, shape); }
277	
278	function forwardBase(coord, shape, layout) {
279	  const flat = flattenCoord(coord, shape);
280	  const comps = splitCoord(flat, layout.shard.map((it) => it.extent));
281	  const phys = {};
282	  for (let k = 0; k < layout.shard.length; k++) {
283	    const it = layout.shard[k];
284	    phys[it.axis] = (phys[it.axis] || 0) + comps[k] * it.stride;
285	  }
286	  for (const axis of Object.keys(layout.offset)) {
287	    phys[axis] = (phys[axis] || 0) + layout.offset[axis];
288	  }
289	  return phys;
290	}
