292	// Replica broadcasts the same logical element onto multiple physical owners:
293	// L(x) = { D(x) + r + O | r in R }.
294	function physOwners(coord, shape, layout) {
295	  let owners = [forwardBase(coord, shape, layout)];
296	  for (const rep of layout.replica) {
297	    const next = [];
298	    for (const o of owners) {
299	      for (let k = 0; k < rep.extent; k++) {
300	        const o2 = Object.assign({}, o);
301	        o2[rep.axis] = (o2[rep.axis] || 0) + k * rep.stride;
302	        next.push(o2);
303	      }
304	    }
305	    owners = next;
306	  }
307	  return owners;
308	}
