310	function axesUsed(layout) {
311	  const s = new Set();
312	  for (const it of layout.shard) s.add(it.axis);
313	  for (const it of layout.replica) s.add(it.axis);
314	  for (const a of Object.keys(layout.offset)) s.add(a);
315	  return AXIS_ORDER.filter((a) => s.has(a));
316	}
317	
318	function coordStr(phys, axes) {
319	  return axes.map((a) => `${a}=${phys[a] || 0}`).join(' ');
320	}
