322	// Swizzle a linear memory address (mirrors src/tirx/ir/layout/compose_layout.cc
323	// ComposeLayoutNode::Apply): low `per_element` bits are kept; above them, the
324	// swizzle bits are XOR'd to scatter bank conflicts.
325	function swizzleAddr(m, sw) {
326	  const base = 1 << sw.per_element;
327	  const innerMask = (1 << sw.swizzle_len) - 1;
328	  const outerMask = innerMask << sw.atom_len;
329	  const x = Math.floor(m / base);
330	  const fx = sw.inner ? (x ^ ((x & outerMask) >> sw.atom_len))
331	                      : (x ^ ((x & innerMask) << sw.atom_len));
332	  return fx * base + (m % base);
333	}
