335	// Resolve the swizzle from the dtype + mode dropdowns (mirrors
336	// tma_utils.mma_shared_layout): per_element = bit_length(128//bits) - 1,
337	// swizzle_len = mode, atom_len = 3. Falls back to an exact ComposeLayout(...,
338	// tile_layout=TileLayout(...)) expression entered in the layout field.
339	const SWIZZLE_LEN = { none: 0, '32': 1, '64': 2, '128': 3 };
340	
341	// Swizzle XOR-permutes a linear shared-memory address, so it only applies when
342	// the layout's sole physical axis is @m (a pure memory layout). With owner or
343	// other storage axes (laneid, warpid, pid, P/F, TLane/TCol, ...) there is no
344	// linear SMEM address to swizzle, and a bank view would be meaningless.
345	function swizzleApplies(layout) {
346	  if (!layout) return false;
347	  const used = axesUsed(layout);
348	  return used.length === 1 && used[0] === 'm';
349	}
