351	function updateSwizzleControls(enabled) {
352	  if (!dtypeSel || !swmodeSel) return;
353	  dtypeSel.disabled = !enabled;
354	  swmodeSel.disabled = !enabled;
355	  const hint = document.getElementById('swhint');
356	  if (hint) hint.hidden = enabled;
357	  const tip = enabled ? '' : tr(
358	    'Swizzle applies only to shared-memory layouts whose sole physical axis is @m',
359	    'Swizzle 只适用于唯一物理轴为 @m 的 shared-memory layout');
360	  dtypeSel.title = tip;
361	  swmodeSel.title = tip;
362	}
