364	function computeSwizzle() {
365	  const mode = swmodeSel ? swmodeSel.value : 'off';
366	  const bits = +(dtypeSel ? dtypeSel.value : 16) || 16;
367	  if (mode === 'off') {
368	    const parsed = ST.layout && ST.layout.swizzle;
369	    return parsed ? { ...parsed, bits } : null;
370	  }
371	  const per_element = Math.floor(128 / bits).toString(2).length - 1;
372	  return {
373	    per_element, swizzle_len: SWIZZLE_LEN[mode] || 0, atom_len: 3, inner: true,
374	    bits, mode,
375	  };
376	}
