404	function recompute() {
405	  ST.error = null; ST.tooBig = false;
406	  try {
407	    ST.shape = splitTopLevel(stripParens(shapeInput.value), ',').map(parseIntStrict);
408	    if (ST.shape.length === 0 || ST.shape.some((x) => x <= 0)) throw new Error('shape must be positive ints');
409	    ST.layout = parseLayout(exprInput.value);
410	  } catch (e) { ST.error = e.message; return; }
411	
412	  const total = product(ST.shape);
413	  if (total > MAX_ELEMENTS) { ST.tooBig = true; return; }
414	
415	  ST.shapeTotal = total;
416	  ST.shardTotal = product(ST.layout.shard.map((it) => it.extent));
417	  ST.mismatch = ST.shardTotal !== total;
418	  ST.swizzleOk = swizzleApplies(ST.layout);
419	  updateSwizzleControls(ST.swizzleOk);
420	  ST.swizzle = ST.swizzleOk ? computeSwizzle() : null;
421	  // elements that share one 4-byte bank word (e.g. 2 fp16, 4 fp8, 1 fp32)
422	  ST.elemsPerBank = ST.swizzle ? Math.max(1, Math.round(4 / ((ST.swizzle.bits || 32) / 8))) : 1;
423	
424	  // 1) owners per element; in swizzle mode, also map the memory address through
425	  //    the swizzle and derive synthetic line/bank coordinates.
426	  ST.byFlat = new Array(total);
427	  for (let flat = 0; flat < total; flat++) {
428	    const owners = physOwners(coordFromFlat(flat, ST.shape), ST.shape, ST.layout);
429	    if (ST.swizzle) {
430	      // A shared-memory bank is 4 bytes; an element occupies dtype_bytes, so the
431	      // bank word index is floor(element_addr * dtype_bytes / 4). 32 banks per line.
432	      const bytes = (ST.swizzle.bits || 32) / 8;
433	      for (const o of owners) {
434	        const sm = swizzleAddr(o.m || 0, ST.swizzle);
435	        const word = Math.floor((sm * bytes) / 4);
436	        o.__sm = sm; o.__word = word; o.bank = word % ST.banks; o.line = Math.floor(word / ST.banks);
437	      }
438	    }
439	    ST.byFlat[flat] = { owners };
440	  }
441	
442	  // 2) choose grid + color axes
443	  if (ST.swizzle) {
444	    ST.gridAxes = ['line', 'bank']; ST.yAxis = 'line'; ST.xAxis = 'bank';
445	    ST.cellAxes = []; ST.colorAxis = 'bank';
446	  } else {
447	    const used = axesUsed(ST.layout);
448	    const owners = used.filter(isOwnerAxis);
449	    ST.gridAxes = owners.length ? owners : used.filter((a) => !isOwnerAxis(a));
450	    ST.yAxis = ST.gridAxes[0] || null;
451	    ST.xAxis = ST.gridAxes[1] || null;
452	    ST.cellAxes = used.filter((a) => !ST.gridAxes.includes(a));
453	    // color axis = first grid axis from shard/offset, so a replica-only row axis
454	    // doesn't collapse every element to one color.
455	    const shardOffsetAxes = new Set(ST.layout.shard.map((it) => it.axis));
456	    for (const a of Object.keys(ST.layout.offset)) shardOffsetAxes.add(a);
457	    ST.colorAxis = ST.gridAxes.find((a) => shardOffsetAxes.has(a)) || ST.gridAxes[0] || null;
458	  }
459	
460	  // 3) build cells, hover keys, colors
461	  ST.byCell = new Map();
462	  const yset = new Set(), xset = new Set(), cset = new Set();
463	  for (let flat = 0; flat < total; flat++) {
464	    const rec = ST.byFlat[flat];
465	    const keys = [];
466	    for (const o of rec.owners) {
467	      const y = ST.yAxis ? (o[ST.yAxis] || 0) : 0;
468	      const x = ST.xAxis ? (o[ST.xAxis] || 0) : 0;
469	      yset.add(y); xset.add(x);
470	      keys.push(gridKey(o, ST.gridAxes));
471	      const ck = y + '#' + x;
472	      if (!ST.byCell.has(ck)) ST.byCell.set(ck, []);
473	      ST.byCell.get(ck).push({
474	        flat,
475	        phys: o,
476	        slot: ST.swizzle ? ('addr ' + o.__sm) : coordStr(o, ST.cellAxes),
477	      });
478	    }
479	    rec.keys = keys;
480	    const cv = ST.colorAxis ? (rec.owners[0][ST.colorAxis] || 0) : 0;
481	    rec.color = paletteColor(cv);
482	    cset.add(cv);
483	  }
484	  ST.yVals = [...yset].sort((a, b) => a - b);
485	  ST.xVals = [...xset].sort((a, b) => a - b);
486	  ST.colorVals = [...cset].sort((a, b) => a - b);
487	}
