730	    html += `<br>swizzle(${sw.per_element},${sw.swizzle_len},${sw.atom_len}, ` +
731	      `inner=${sw.inner ? 'True' : 'False'}): ` +
732	      `m=${o0.m || 0} → elem ${o0.__sm} → byte ${o0.__sm * bytes} → ` +
733	      `<b>bank ${o0.bank}</b>, line ${o0.line} (${bytes}-byte dtype, 4-byte banks ×32)`;
734	  }
735	  if (owners.length > 1) {
736	    html += `<br>${tr('owners', '物理位置')} (×${owners.length}, replica): ` +
737	      owners.map((o) => '{ ' + coordStr(o, ST.gridAxes) + ' }').join('  ,  ');
738	  }
739	  html += '</div>';
740	  fb.innerHTML = html;
741	}
