743	// ── Arrow overlay (adapted from the course draw pattern) ───────────────────--
744	const panels = document.getElementById('panels');
745	const arrowSvg = document.getElementById('arrow');
746	
747	function drawArrow() {
748	  arrowSvg.innerHTML = '';
749	  if (hovFlat === null) return;
750	  const leftCell = document.querySelector('#g0 .cell.hov');
751	  const rightCells = document.querySelectorAll('#phys .gcell.hov');
752	  if (!leftCell || rightCells.length === 0) return;
753	  const pr = panels.getBoundingClientRect();
754	  const ns = 'http://www.w3.org/2000/svg';
755	  const defs = document.createElementNS(ns, 'defs');
756	  const marker = document.createElementNS(ns, 'marker');
757	  marker.setAttribute('id', 'ah'); marker.setAttribute('markerWidth', '8'); marker.setAttribute('markerHeight', '6');
758	  marker.setAttribute('refX', '7'); marker.setAttribute('refY', '3'); marker.setAttribute('orient', 'auto');
759	  const poly = document.createElementNS(ns, 'polygon');
760	  poly.setAttribute('points', '0 0, 8 3, 0 6'); poly.setAttribute('fill', '#222');
761	  marker.appendChild(poly); defs.appendChild(marker); arrowSvg.appendChild(defs);
762	  const a = leftCell.getBoundingClientRect();
763	  const x1 = a.left + a.width / 2 - pr.left, y1 = a.top + a.height / 2 - pr.top;
764	  rightCells.forEach((rc) => {
765	    const b = rc.getBoundingClientRect();
766	    const x2 = b.left + b.width / 2 - pr.left, y2 = b.top + b.height / 2 - pr.top;
767	    const mx = (x1 + x2) / 2, my = Math.min(y1, y2) - 24;
768	    const path = document.createElementNS(ns, 'path');
769	    path.setAttribute('d', `M${x1},${y1} Q${mx},${my} ${x2},${y2}`);
770	    path.setAttribute('marker-end', 'url(#ah)');
771	    arrowSvg.appendChild(path);
772	  });
