867	  { label: tr('Blackwell tensor memory (TLane/TCol)', 'Blackwell TMEM（TLane/TCol）'), shape: '4, 8', expr: 'S[(2,4,4):(4@TCol,1@TLane,1@TCol)]' },
868	  { label: tr('SMEM, no swizzle (bank conflicts)', 'SMEM，无 swizzle（bank conflict）'), shape: '8, 64', expr: 'S[(8,64):(64@m,1@m)]', dtype: 16, mode: 'none' },
